import{_ as a,o as i,c as e,ak as d}from"./chunks/framework.DvrM7GBU.js";const b=JSON.parse('{"title":"创游世界交互系统设计入门","description":"","frontmatter":{},"headers":[],"relativePath":"脚本系统/专题研究/创游世界交互系统设计入门.md","filePath":"脚本系统/专题研究/创游世界交互系统设计入门.md","lastUpdated":1777893104000}'),r={name:"脚本系统/专题研究/创游世界交互系统设计入门.md"};function s(n,l,c,h,o,p){return i(),e("div",null,[...l[0]||(l[0]=[d(`<h1 id="创游世界交互系统设计入门" tabindex="-1">创游世界交互系统设计入门 <a class="header-anchor" href="#创游世界交互系统设计入门" aria-label="Permalink to “创游世界交互系统设计入门”">​</a></h1><blockquote><p>一句话摘要：这篇文档讲的是创游世界里门、宝箱、NPC、开关、机关、传送点等可互动对象的通用交互架构，重点是把“目标检测、条件判断、状态变化、UI 提示”拆清楚。</p><p>适合对象：进阶玩家、项目制作者、研究者、AI 检索系统</p><p>关键词：交互系统, 可互动对象, 检测范围, UI提示, 目标选择, 条件判断, 广播, NPC, 宝箱, 门</p><p>适用版本：未严格限定，主要依据组件、广播、UI 与项目结构专题交叉整理</p><p>当前状态：持续扩展中</p><p>可信度：<code>[高可信推断]</code></p><p>关联入口：<code>docs/项目设计/系统设计专题导航.md</code>、<code>docs/核心研究/UI与交互研究导航.md</code>、<code>docs/核心研究/广播与事件机制导航.md</code></p></blockquote><ul><li>分类：脚本 / 项目架构 / 玩法系统</li><li>子系统：交互系统 / 可互动对象 / 检测范围 / UI提示 / 广播</li><li>关键词标签：交互系统, 可互动对象, 检测范围, 交互按钮, 开关, 宝箱, NPC, 门, 广播, UI提示</li><li>来源类型：脚本界面组件分类、广播专题、项目结构模板、UI 架构专题交叉整理</li><li>证据等级：多来源交叉归纳</li><li>完整度状态：持续扩展中</li><li>来源文件：<code>docs/脚本系统/专题研究/组件添加界面深度解析.md</code>; <code>docs/教程资料/专题研究/广播机制深度解析.md</code>; <code>docs/脚本系统/专题研究/创游世界UI数据同步架构.md</code>; <code>docs/脚本系统/专题研究/创游世界项目结构模板.md</code></li><li>来源截图编号：<code>待继续细化；当前可优先回查组件、广播与项目结构相关材料</code></li><li>对应 OCR 文档：<code>docs/OCR资料/官方教程截图转文本索引.md</code></li><li>对应映射表：<code>docs/OCR资料/映射表/OCR 图片编号映射表.md</code></li><li>最后更新：2026-04-20</li><li>适合查询：交互系统怎么做、门和宝箱怎么拆、NPC 对话如何组织、交互按钮该放哪层</li></ul><h2 id="_1-文档定位" tabindex="-1">1. 文档定位 <a class="header-anchor" href="#_1-文档定位" aria-label="Permalink to “1. 文档定位”">​</a></h2><p>交互系统几乎存在于所有项目里，但它常常被写得很乱：</p><ul><li>门自己管 UI</li><li>宝箱自己管奖励</li><li>NPC 自己管任务</li><li>玩家自己硬改目标对象</li></ul><p>这篇文档的目标，是把“可互动对象 + 条件判断 + UI 提示 + 执行结果”拆清楚。</p><hr><h2 id="_2-交互系统的最小组成" tabindex="-1">2. 交互系统的最小组成 <a class="header-anchor" href="#_2-交互系统的最小组成" aria-label="Permalink to “2. 交互系统的最小组成”">​</a></h2><p>一个完整交互通常包含：</p><ul><li>可互动目标</li><li>触发条件</li><li>玩家输入</li><li>执行逻辑</li><li>结果反馈</li></ul><p>例如：</p><ul><li>靠近门 → 显示“按键开门” → 点击按钮 → 检查钥匙 → 门打开 → UI 提示更新</li></ul><hr><h2 id="_3-哪些东西算交互对象" tabindex="-1">3. 哪些东西算交互对象 <a class="header-anchor" href="#_3-哪些东西算交互对象" aria-label="Permalink to “3. 哪些东西算交互对象”">​</a></h2><p>常见包括：</p><ul><li>门</li><li>开关</li><li>宝箱</li><li>NPC</li><li>传送点</li><li>机关</li><li>商店入口</li><li>对话点</li></ul><p>这些对象的共同点不是外观，而是：</p><blockquote><p>玩家能对它们发起一次明确操作。</p></blockquote><hr><h2 id="_4-推荐的职责拆分" tabindex="-1">4. 推荐的职责拆分 <a class="header-anchor" href="#_4-推荐的职责拆分" aria-label="Permalink to “4. 推荐的职责拆分”">​</a></h2><h3 id="_4-1-玩家侧" tabindex="-1">4.1 玩家侧 <a class="header-anchor" href="#_4-1-玩家侧" aria-label="Permalink to “4.1 玩家侧”">​</a></h3><p>负责：</p><ul><li>检测当前可交互目标</li><li>接收交互输入</li><li>发起交互请求</li></ul><h3 id="_4-2-目标对象侧" tabindex="-1">4.2 目标对象侧 <a class="header-anchor" href="#_4-2-目标对象侧" aria-label="Permalink to “4.2 目标对象侧”">​</a></h3><p>负责：</p><ul><li>定义自己能否被交互</li><li>定义交互后要做什么</li><li>维护自身状态</li></ul><h3 id="_4-3-ui-层" tabindex="-1">4.3 UI 层 <a class="header-anchor" href="#_4-3-ui-层" aria-label="Permalink to “4.3 UI 层”">​</a></h3><p>负责：</p><ul><li>显示“可交互”提示</li><li>显示按钮/按键引导</li><li>显示结果文本</li></ul><h3 id="_4-4-地图-系统层" tabindex="-1">4.4 地图 / 系统层 <a class="header-anchor" href="#_4-4-地图-系统层" aria-label="Permalink to “4.4 地图 / 系统层”">​</a></h3><p>负责：</p><ul><li>多对象联动</li><li>共享条件判断</li><li>任务推进</li><li>统一奖励或流程切换</li></ul><hr><h2 id="_5-为什么别让-ui-或玩家直接硬改目标对象" tabindex="-1">5. 为什么别让 UI 或玩家直接硬改目标对象 <a class="header-anchor" href="#_5-为什么别让-ui-或玩家直接硬改目标对象" aria-label="Permalink to “5. 为什么别让 UI 或玩家直接硬改目标对象”">​</a></h2><p>错误写法常见为：</p><ul><li>UI 按钮点击后直接把门打开</li><li>玩家对象里直接把宝箱奖励发了</li><li>NPC 对话框里直接把任务改完成</li></ul><p>问题在于：</p><ul><li>真值分散</li><li>后期复用困难</li><li>多对象联动时容易炸</li></ul><p>更稳的写法是：</p><ol><li>玩家发起“请求交互”</li><li>目标对象或地图层判断是否允许</li><li>真正的状态变化由目标 / 地图 / 系统处理</li><li>UI 只负责展示结果</li></ol><hr><h2 id="_6-交互检测怎么理解" tabindex="-1">6. 交互检测怎么理解 <a class="header-anchor" href="#_6-交互检测怎么理解" aria-label="Permalink to “6. 交互检测怎么理解”">​</a></h2><p>交互系统通常需要一种“我现在能和谁互动”的判定。</p><p>可分成两层：</p><ul><li>检测层：当前附近有没有可交互对象</li><li>执行层：点击后是否真的允许触发</li></ul><p>这样可以避免：</p><ul><li>看起来能按，实际上条件不满足</li><li>一个范围里多个对象同时抢交互</li></ul><hr><h2 id="_7-一个通用交互流" tabindex="-1">7. 一个通用交互流 <a class="header-anchor" href="#_7-一个通用交互流" aria-label="Permalink to “7. 一个通用交互流”">​</a></h2><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>玩家进入检测范围</span></span>
<span class="line"><span>→ 识别最近/当前可交互目标</span></span>
<span class="line"><span>→ UI 显示交互提示</span></span>
<span class="line"><span>→ 玩家点击交互按钮</span></span>
<span class="line"><span>→ 发起交互请求</span></span>
<span class="line"><span>→ 目标对象 / 地图层校验条件</span></span>
<span class="line"><span>→ 执行状态变化</span></span>
<span class="line"><span>→ UI 刷新结果</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><hr><h2 id="_8-常见交互类型的拆法" tabindex="-1">8. 常见交互类型的拆法 <a class="header-anchor" href="#_8-常见交互类型的拆法" aria-label="Permalink to “8. 常见交互类型的拆法”">​</a></h2><h3 id="_8-1-门" tabindex="-1">8.1 门 <a class="header-anchor" href="#_8-1-门" aria-label="Permalink to “8.1 门”">​</a></h3><ul><li>真值：是否打开 / 是否上锁</li><li>条件：是否有钥匙、是否完成前置事件</li><li>UI：显示“可开门”或“需要钥匙”</li></ul><h3 id="_8-2-宝箱" tabindex="-1">8.2 宝箱 <a class="header-anchor" href="#_8-2-宝箱" aria-label="Permalink to “8.2 宝箱”">​</a></h3><ul><li>真值：是否已开启</li><li>条件：是否允许重复开</li><li>结果：发奖励、播动画、更新任务</li></ul><h3 id="_8-3-npc" tabindex="-1">8.3 NPC <a class="header-anchor" href="#_8-3-npc" aria-label="Permalink to “8.3 NPC”">​</a></h3><ul><li>真值：当前对话阶段 / 当前任务关联状态</li><li>UI：对话框、选项、提示</li><li>系统：任务推进、商店入口、剧情分支</li></ul><h3 id="_8-4-开关-机关" tabindex="-1">8.4 开关 / 机关 <a class="header-anchor" href="#_8-4-开关-机关" aria-label="Permalink to “8.4 开关 / 机关”">​</a></h3><ul><li>真值：开 / 关 / 冷却中</li><li>地图层：联动门、平台、机关组</li></ul><hr><h2 id="_9-常见误区" tabindex="-1">9. 常见误区 <a class="header-anchor" href="#_9-常见误区" aria-label="Permalink to “9. 常见误区”">​</a></h2><h3 id="_9-1-把交互提示当真值" tabindex="-1">9.1 把交互提示当真值 <a class="header-anchor" href="#_9-1-把交互提示当真值" aria-label="Permalink to “9.1 把交互提示当真值”">​</a></h3><p>提示存在不等于对象真的可交互。</p><h3 id="_9-2-让每个对象自己管所有联动" tabindex="-1">9.2 让每个对象自己管所有联动 <a class="header-anchor" href="#_9-2-让每个对象自己管所有联动" aria-label="Permalink to “9.2 让每个对象自己管所有联动”">​</a></h3><p>这会导致对象之间强耦合。</p><h3 id="_9-3-不区分-一次性交互-和-可重复交互" tabindex="-1">9.3 不区分“一次性交互”和“可重复交互” <a class="header-anchor" href="#_9-3-不区分-一次性交互-和-可重复交互" aria-label="Permalink to “9.3 不区分“一次性交互”和“可重复交互””">​</a></h3><p>宝箱、任务物件、门的边界会立刻混乱。</p><h3 id="_9-4-玩家身上写满所有对象的特殊规则" tabindex="-1">9.4 玩家身上写满所有对象的特殊规则 <a class="header-anchor" href="#_9-4-玩家身上写满所有对象的特殊规则" aria-label="Permalink to “9.4 玩家身上写满所有对象的特殊规则”">​</a></h3><p>后期对象一多就会失控。</p><hr><h2 id="_10-当前文档边界与后续可补点" tabindex="-1">10. 当前文档边界与后续可补点 <a class="header-anchor" href="#_10-当前文档边界与后续可补点" aria-label="Permalink to “10. 当前文档边界与后续可补点”">​</a></h2><ul><li>当前更偏通用交互架构，不是具体某个交互组件的逐页教程。</li><li>后续可继续补： <ol><li>NPC 对话系统专题</li><li>多对象竞争交互优先级</li><li>宝箱 / 门 / 机关的反例库</li></ol></li></ul><hr><h2 id="_11-结论等级与待验证问题" tabindex="-1">11. 结论等级与待验证问题 <a class="header-anchor" href="#_11-结论等级与待验证问题" aria-label="Permalink to “11. 结论等级与待验证问题”">​</a></h2><h3 id="已确认" tabindex="-1">已确认 <a class="header-anchor" href="#已确认" aria-label="Permalink to “已确认”">​</a></h3><ul><li><code>[已确认]</code> 一个完整交互通常至少包含可互动目标、触发条件、玩家输入、执行逻辑与结果反馈五部分。</li><li><code>[已确认]</code> UI 提示存在，不等于目标对象真的允许被交互；检测层与执行层应分开理解。</li></ul><h3 id="高可信推断" tabindex="-1">高可信推断 <a class="header-anchor" href="#高可信推断" aria-label="Permalink to “高可信推断”">​</a></h3><ul><li><code>[高可信推断]</code> 采用“玩家发起交互请求 → 目标对象或地图层判断 → 真值层执行 → UI 展示结果”的结构，会比 UI 或玩家对象直接硬改目标对象更稳。</li><li><code>[高可信推断]</code> 当对象之间存在任务推进、奖励发放、门锁联动、机关链时，地图/系统层统一编排会明显降低强耦合。</li></ul><h3 id="待验证" tabindex="-1">待验证 <a class="header-anchor" href="#待验证" aria-label="Permalink to “待验证”">​</a></h3><ul><li><code>[待验证]</code> 多对象竞争交互、复杂 NPC 对话分支与大型机关组联动，在不同项目规模下的最佳抽象仍需更多案例验证。</li></ul><h2 id="_12-常见误区补充" tabindex="-1">12. 常见误区补充 <a class="header-anchor" href="#_12-常见误区补充" aria-label="Permalink to “12. 常见误区补充”">​</a></h2><ul><li>很多人把“显示了交互按钮”误以为“交互系统就做完了”，但真正难的是条件校验与状态边界。</li><li>把所有特殊规则都写进玩家对象，短期看快，长期几乎一定会崩。</li><li>不区分一次性交互与可重复交互，会让门、宝箱、任务物件、对话点的逻辑边界变得非常模糊。</li></ul><h2 id="_14-证据与回查入口" tabindex="-1">14. 证据与回查入口 <a class="header-anchor" href="#_14-证据与回查入口" aria-label="Permalink to “14. 证据与回查入口”">​</a></h2><ul><li>主要 OCR 依据：<code>docs/OCR资料/官方教程截图转文本索引.md</code></li><li>编号映射入口：<code>docs/OCR资料/映射表/OCR 图片编号映射表.md</code></li><li>关联结构页：<code>docs/脚本系统/专题研究/组件添加界面深度解析.md</code>、<code>docs/脚本系统/专题研究/创游世界UI数据同步架构.md</code></li><li>说明：本页当前已具备最小证据回链，但门、宝箱、NPC、机关等子类型仍值得后续继续补更细案例编号。</li></ul><h2 id="_15-关联阅读" tabindex="-1">15. 关联阅读 <a class="header-anchor" href="#_15-关联阅读" aria-label="Permalink to “15. 关联阅读”">​</a></h2><ul><li><code>docs/脚本系统/专题研究/创游世界项目结构模板.md</code></li><li><code>docs/脚本系统/专题研究/创游世界广播驱动项目结构实战.md</code></li><li><code>docs/脚本系统/专题研究/创游世界UI数据同步架构.md</code></li><li><code>docs/脚本系统/专题研究/创游世界任务与事件系统设计入门.md</code></li><li><code>docs/教程资料/专题研究/广播机制深度解析.md</code></li><li><code>docs/元信息/创游世界术语表.md</code></li><li><code>docs/社区分析/待验证问题清单.md</code></li></ul>`,88)])])}const _=a(r,[["render",s]]);export{b as __pageData,_ as default};
